        "quote": "肺栓塞诊断明确"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00304",
        "explanation": "针对疲劳和易混淆状态，将出院前任务压缩成可现场照读的三项清单。",
        "quote": "给您一个最简对照"
      }
    ]
  },
